    return next(e)
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: /(?<guardback>)/ }, async ($, e, next) => {
    const i = io($)
    const sid = await i.sessionId()
    const tool = String(e.tool)
    const args = argsOf(e)
    let mode: Mode = 'off'
    let found: BackFound[] = []
    try {
