        const offer = await undoOffer(i)
        const fresh = takeFresh(heldSeen, found, f => `${sid}|${f.key}`)
        if (fresh.length > 0) {
          await ledger(i, sid, HELD_WHAT, detailOf(fresh), 'auto')
          i.toast(`${heldToast()}${offer.toast}`, true)
          i.invalidate()
