// The 15 registered slash commands; every other function is a word after one of them or a name after `/vaken-help run`.

import { tEn } from '../i18n/t'

export const FRONT_DOOR: string[] = [
  'vaken',
  'vaken-help',
  'vaken-settings',
  'vaken-usage',
